  byId.pereiaslav.src = 'Encyclopedia of Ukraine; Magocsi, “A History of Ukraine”.';
  byId.holodomor.src = 'Demographic scholarship 3.5–5M+ (Rudnytsky et al.); recognized as genocide by Ukraine and many states.';
